package app.patchwork.radar;
import org.json.*;
import org.junit.Test;
import java.time.*;
import java.util.*;
import static org.junit.Assert.*;
public class ReminderPolicyTest {
 private final long NOW=Instant.parse("2026-10-16T03:00:00Z").toEpochMilli();
 private JSONObject prefs()throws Exception{return new JSONObject("{\"enabled\":true,\"locale\":\"ko\",\"region\":\"kr\",\"games\":[\"wuwa\",\"arknights\"],\"gameRegions\":{},\"kinds\":[\"pickup\",\"weapon\",\"event\",\"package\"],\"offsets\":[1440,60],\"starts\":true,\"quietEnabled\":false}");}
 private JSONObject entry(String id,String game,String region,String end)throws Exception{return new JSONObject().put("id",id).put("gameId",game).put("region",region).put("kind","pickup").put("startAt","2026-10-15T12:00:00+09:00").put("endAt",end);}
 private JSONObject feed(JSONObject... entries)throws Exception{return new JSONObject().put("games",new JSONArray("[{\"id\":\"wuwa\",\"canonicalRegions\":{\"kr\":\"global\",\"jp\":\"global\",\"global\":\"global\"}},{\"id\":\"arknights\",\"canonicalRegions\":{\"kr\":\"kr\",\"jp\":\"jp\",\"global\":\"global\"}}]")).put("entries",new JSONArray(Arrays.asList(entries)));}
 @Test public void usesSharedScheduleAndKeepsActualRegionalDifferences()throws Exception{JSONObject f=feed(entry("wuwa","wuwa","global","2026-10-18T12:00:00+09:00"),entry("kr","arknights","kr","2026-10-17T12:00:00+09:00"),entry("jp","arknights","jp","2026-10-17T12:00:00+09:00"));List<JSONObject> rows=ReminderPolicy.deadlines(f,prefs(),NOW);assertEquals(2,rows.size());assertEquals("kr",rows.get(0).getString("id"));assertEquals("wuwa",rows.get(1).getString("id"));}
 @Test public void gameSpecificServerSelectionWins()throws Exception{JSONObject p=prefs();p.getJSONObject("gameRegions").put("arknights","jp");JSONObject f=feed(entry("kr","arknights","kr","2026-10-18T12:00:00+09:00"),entry("jp","arknights","jp","2026-10-18T12:00:00+09:00"));assertEquals("jp",ReminderPolicy.deadlines(f,p,NOW).get(0).getString("id"));}
 @Test public void schedulesVerifiedOffsetsWithCorrectTimezone()throws Exception{JSONObject f=feed(entry("a","wuwa","global","2026-10-18T12:00:00+09:00"));List<ReminderPolicy.Reminder> plan=ReminderPolicy.plan(f,prefs(),NOW,ZoneId.of("Asia/Tokyo"));assertEquals(2,plan.size());assertEquals(Instant.parse("2026-10-17T03:00:00Z").toEpochMilli(),plan.get(0).fireAt);assertEquals(Instant.parse("2026-10-18T02:00:00Z").toEpochMilli(),plan.get(1).fireAt);}
 @Test public void expiredAndUnknownEndNeverProduceDeadlineReminders()throws Exception{JSONObject unknown=entry("unknown","wuwa","global","");JSONObject f=feed(unknown,entry("past","wuwa","global","2026-10-15T12:00:00+09:00"));assertTrue(ReminderPolicy.plan(f,prefs(),NOW,ZoneId.of("Asia/Tokyo")).isEmpty());assertTrue(ReminderPolicy.deadlines(f,prefs(),NOW).isEmpty());}
 @Test public void quietHoursCrossMidnightAndRespectDeviceZone()throws Exception{JSONObject p=prefs().put("quietEnabled",true).put("quietStart",23).put("quietEnd",8);assertTrue(ReminderPolicy.quietAt(Instant.parse("2026-10-16T15:00:00Z").toEpochMilli(),p,ZoneId.of("Asia/Tokyo")));assertFalse(ReminderPolicy.quietAt(Instant.parse("2026-10-16T15:00:00Z").toEpochMilli(),p,ZoneId.of("America/New_York")));}
 @Test public void disabledNotificationsStillPermitWidgetData()throws Exception{JSONObject p=prefs().put("enabled",false);JSONObject f=feed(entry("a","wuwa","global","2026-10-18T12:00:00+09:00"));assertTrue(ReminderPolicy.plan(f,p,NOW,ZoneId.of("Asia/Tokyo")).isEmpty());assertEquals(1,ReminderPolicy.deadlines(f,p,NOW).size());}
 @Test public void correctedDeadlineChangesIdentityForCancellation()throws Exception{JSONObject p=prefs(),old=feed(entry("a","wuwa","global","2026-10-18T12:00:00+09:00")),updated=feed(entry("a","wuwa","global","2026-10-19T12:00:00+09:00"));assertNotEquals(ReminderPolicy.plan(old,p,NOW,ZoneId.of("Asia/Tokyo")).get(0).key(),ReminderPolicy.plan(updated,p,NOW,ZoneId.of("Asia/Tokyo")).get(0).key());}
 @Test public void noChineseScheduleOrUnselectedGame()throws Exception{JSONObject f=feed(entry("cn","wuwa","cn","2026-10-18T12:00:00+09:00"));assertTrue(ReminderPolicy.deadlines(f,prefs(),NOW).isEmpty());assertFalse(ReminderPolicy.GAME_IDS.contains("cn"));}
}
